import React, { useState, useEffect } from 'react';
import { getProjetosByCliente } from '../api/ProjetoApi';

const ProjetoList = ({ clienteId }) => {
  const [projetos, setProjetos] = useState([]);

  useEffect(() => {
    getProjetosByCliente(clienteId)
      .then(response => setProjetos(response))
      .catch(error => console.error('Erro ao buscar projetos', error));
  }, [clienteId]);

  return (
    <div>
      <h3>Projetos</h3>
      <ul>
        {projetos.map(projeto => (
          <li key={projeto.id}>
            {projeto.nome} - {projeto.descricao}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ProjetoList;
